package com.stitchtrack.controller;
import com.google.zxing.*;import com.google.zxing.client.j2se.MatrixToImageWriter;import com.google.zxing.common.BitMatrix;import com.google.zxing.qrcode.QRCodeWriter;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/qr") public class QRServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{String token=r.getParameter("token");if(token==null||token.isBlank()){s.sendError(400);return;}try{BitMatrix m=new QRCodeWriter().encode(token,BarcodeFormat.QR_CODE,280,280);s.setContentType("image/png");s.setHeader("Cache-Control","no-store");MatrixToImageWriter.writeToStream(m,"PNG",s.getOutputStream());}catch(WriterException e){throw new IOException(e);}}}
